-- Aplicada via MCP el 2026-11-12
-- Rescatada el 17/nov copiando tal cual supabase_migrations.schema_migrations
-- (version 20261112210315). Numero 0141 porque 0101 ya estaba tomado.
-- Datos recibidos por WhatsApp: stock, costos de compra y recetas de Cochi.

with datos(name, unit, cost, stock, category, food_category) as (values ('Milanesa de pollo','kg',6.00,13.850,'Proteínas','carne'),('Alitas de pollo','kg',3.80,8.430,'Proteínas','carne'),('Lomito','kg',12.00,6.280,'Proteínas','carne'),('Carne segunda','kg',10.50,2.850,'Proteínas','carne'),('Pollo entero','unidad',3.25,7,'Proteínas','carne'),('Jamón','kg',12.50,3.825,'Proteínas','carne'),('Camarones','kg',10.00,4,'Proteínas','mariscos'),('Pan','unidad',0,0,'Shawarma','panificados'),('Pollo','g',0,0,'Shawarma','carne'),('Lechuga','g',0,0,'Shawarma','vegetales'),('Tomate','g',0,0,'Shawarma','vegetales'),('Cebolla','g',0,0,'Shawarma','vegetales'),('Perejil','g',0,0,'Shawarma','vegetales'),('Pepinillo','g',0,0,'Shawarma','vegetales'),('Salsa ajo','g',0,0,'Shawarma','salsas'),('Salsa tahina','g',0,0,'Shawarma','salsas'),('Papitas','g',0,0,'Shawarma','acompañamientos')) insert into public.ingredients(tenant_id,name,unit,cost,stock,category,food_category) select t.id,d.name,d.unit,d.cost,0,d.category,d.food_category from public.tenants t cross join datos d where t.slug='cochi' and not exists(select 1 from public.ingredients i where i.tenant_id=t.id and lower(btrim(i.name))=lower(btrim(d.name))); with stock(name,qty,unit_cost) as (values ('Milanesa de pollo',13.850,6.00),('Alitas de pollo',8.430,3.80),('Lomito',6.280,12.00),('Carne segunda',2.850,10.50),('Pollo entero',7,3.25),('Jamón',3.825,12.50),('Camarones',4,10.00)) insert into public.inventory_movements(tenant_id,branch_id,ingredient_id,kind,qty,unit_cost,reference_type,note) select t.id,b.id,i.id,'initial',s.qty,s.unit_cost,'whatsapp','Stock inicial informado por Cochi el 2026-11-12' from public.tenants t join public.branches b on b.tenant_id=t.id and b.is_default join stock s on true join public.ingredients i on i.tenant_id=t.id and lower(btrim(i.name))=lower(btrim(s.name)) where t.slug='cochi' and not exists(select 1 from public.inventory_movements m where m.tenant_id=t.id and m.ingredient_id=i.id and m.reference_type='whatsapp' and m.kind='initial'); insert into public.recipe_cards(tenant_id,product_id,yield_qty,yield_unit,steps,notes) select t.id,p.id,1,'unidad',jsonb_build_array(jsonb_build_object('texto','Armar el shawarma con pan árabe, pollo, lechuga, tomate, cebolla, perejil, pepinillo, salsa ajo, salsa tahina y papitas.'),jsonb_build_object('texto','Marinado de pollo para 10 kg: 10 limones (175 g), 75 g de ajo en polvo, 40 g de comino, 30 g de 7 especies, 30 g de paprika, 40 g de pimienta, 150 g de sal, 60 g de color, 120 g de vinagre y 100 g de aceite.'),jsonb_build_object('texto','Pasta de ajonjolí: 250 g de ajonjolí y 60 g de aceite.'),jsonb_build_object('texto','Salsa tahina: 3,3 kg de mayonesa, 150 g de pasta de ajonjolí, 90 g de limón, 40 g de sal, 2 g de pimienta, 2 g de comino, 400 ml de agua y 20 g de ajo en polvo.'),jsonb_build_object('texto','Aderezo César: 3,3 kg de mayonesa, 90 g de limón, 300 g de tocineta, 60 g de mostaza, 30 g de salsa inglesa, 8 g de ajo, 1 g de pimienta y 40 g de sal.'),jsonb_build_object('texto','Ensalada César: 250 g de lechuga, 60 g de aderezo César, 5 g de crotones y 60 g de queso pecorino.')),'Porción informada por Cochi: pan 1 unidad, pollo 200 g, lechuga 30 g, tomate 30 g, cebolla 20 g, perejil 1 g, pepinillo 40 g, salsa ajo 30 g, salsa tahina 60 g y papitas 20 g.' from public.tenants t join public.products p on p.tenant_id=t.id and lower(p.name)='shawarma de pollo' where t.slug='cochi' and not exists(select 1 from public.recipe_cards rc where rc.tenant_id=t.id and rc.product_id=p.id); with receta(name,qty) as (values ('Pan',1),('Pollo',200),('Lechuga',30),('Tomate',30),('Cebolla',20),('Perejil',1),('Pepinillo',40),('Salsa ajo',30),('Salsa tahina',60),('Papitas',20)) insert into public.product_ingredients(tenant_id,product_id,ingredient_id,qty) select t.id,p.id,i.id,r.qty from public.tenants t join public.products p on p.tenant_id=t.id and lower(p.name)='shawarma de pollo' join receta r on true join public.ingredients i on i.tenant_id=t.id and lower(i.name)=lower(r.name) where t.slug='cochi' and not exists(select 1 from public.product_ingredients pi where pi.product_id=p.id and pi.ingredient_id=i.id);
